<?php $bp=defined('BASE_PATH')?BASE_PATH:''; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ob_start(); ?><div class="container-fluid py-4"><div class="mb-4"><span class="eyebrow">Regra financeira</span><h1>Comissões do Programa de Indicação</h1><p class="text-muted">O parceiro recebe um percentual da comissão da GuinchaFácil, nunca do valor total do pedido.</p></div><?php if (!empty($_GET['ok'])): ?><div class="alert alert-success"><?= $_GET['ok']==='status'?'Status da comissão atualizado.':'Regra criada e ativada.' ?></div><?php endif; ?><?php if (!empty($erro)): ?><div class="alert alert-warning"><?= $e($erro) ?></div><?php endif; ?><div class="row g-4"><div class="col-xl-5"><div class="card shadow-sm"><div class="card-header"><strong>Nova regra</strong></div><div class="card-body"><form method="post" action="<?= $e($bp) ?>/admin/marketing/comissoes-indicacao/salvar"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><label class="form-label">Perfil</label><select class="form-select mb-3" name="partner_profile"><option value="distribuicao">Programa de indicação</option><option value="guincho">Guincho</option><option value="oficina">Oficina</option></select><label class="form-label">Participação sobre a comissão GF (%)</label><input class="form-control mb-3" name="referral_share_percent" type="number" min="0" max="100" step="0.01" value="0" required><label class="form-label">Desconto do cliente (%)</label><input class="form-control mb-3" name="discount_percent" type="number" min="0" max="100" step="0.01" value="0" required><button class="btn btn-primary">Ativar regra</button></form></div></div></div><div class="col-xl-7"><div class="card shadow-sm"><div class="card-header"><strong>Histórico de regras</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Perfil</th><th>Parceiro sobre comissão GF</th><th>Desconto cliente</th><th>Status</th><th>Vigência</th><th>Ação</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= $e($row['partner_profile']) ?></td><td><?= $e($row['commission_percent']) ?>%</td><td><?= $e($row['discount_percent']) ?>%</td><td><?= $e($row['status']) ?></td><td><?= $e($row['effective_from']) ?></td><td><form method="post" action="<?= $e($bp) ?>/admin/marketing/comissoes-indicacao/status"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-sm <?= $row['status']==='ativo'?'btn-outline-warning':'btn-outline-success' ?>"><?= $row['status']==='ativo'?'Pausar':'Ativar' ?></button></form></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="text-muted">Nenhuma regra configurada.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div><?php $conteudo_pagina=ob_get_clean(); $perfil='admin'; $titulo_pagina='Comissões de indicação'; $breadcrumb=['Marketing','Comissões']; $assets_css=['/public/assets/css/pages/bo-admin-financeiro.css']; require __DIR__ . '/../layouts/backoffice_shell.php';
